function validate([words]) {
  if (!Array.isArray(words) || words.length < 1 || words.length > 100) return 'words needs 1 to 100 strings.';
  for (const word of words) {
    if (typeof word !== 'string' || word.length < 1 || word.length > 100) return 'Each word has 1 to 100 characters.';
    if (!/^[a-z]+$/.test(word)) return 'Words contain only lowercase English letters.';
  }
  return null;
}

