function commonChars(words) {
  // Take each letter of the first word and try to cross off one copy of it in every other word.
  const rest = words.slice(1).map(w => w.split(''));
  const result = [];
  for (const ch of words[0]) {
    if (rest.every(letters => letters.includes(ch))) {
      for (const letters of rest) letters.splice(letters.indexOf(ch), 1);
      result.push(ch);
    }
  }
  return result;
}

