function generate(rand, size) {
  const large = size === 'large';
  const count = large ? 50 + Math.floor(rand() * 51) : 1 + Math.floor(rand() * 4);
  const maxLen = large ? 100 : 6;
  const alphabet = large ? 1 + Math.floor(rand() * 26) : 1 + Math.floor(rand() * 4);
  const letter = () => String.fromCharCode(97 + Math.floor(rand() * alphabet));
  // A shared core of letters makes non-empty answers likely; extra letters vary each word.
  const coreSize = Math.floor(rand() * (maxLen / 2 + 1));
  const core = Array.from({ length: coreSize }, letter);
  const words = [];
  for (let w = 0; w < count; w++) {
    const length = Math.max(1, coreSize + Math.floor(rand() * (maxLen - coreSize + 1)));
    const letters = core.slice(0, Math.min(coreSize, length));
    while (letters.length < length) letters.push(letter());
    for (let i = letters.length - 1; i > 0; i--) {
      const j = Math.floor(rand() * (i + 1));
      [letters[i], letters[j]] = [letters[j], letters[i]];
    }
    words.push(letters.join(''));
  }
  return [words];
}
